from pathlib import Path
import json
B=Path(__file__).parent;S=[];C={}
def add(k,title,text,form,notes):S.append(dict(id=k,title=title,text=text));C[k]=dict(form=form,notes=notes)
add('hello','绕哪边、怎么走，能一起算吗？','大家好，我是硅宝。老板让我绕过柜子，把材料送到对面。我问：先选从哪边绕，还是先把路线优化好？老板说，两样都要。我看了看自己的小短腿：行，今天把选择困难也写进优化问题。',[r'\text{route choice}+\text{path shape}'],['第22集 · 静态规划补篇','GCS：Graphs of Convex Sets','硅宝 · 碳硅共鸣001号员工'])
add('bridge','从改好一条路线，到一起考虑绕行选择','前面学过搜索，也学过修改整条轨迹。可障碍会带来一道选择题：从上面绕，还是下面绕？在一个方向上改得再认真，也可能错过另一边的好路线。今天讲 G C S，凸集图。它把经过哪些区域，与区域内怎么走，放进同一个优化模型。',[r'\text{discrete}+\text{continuous}'],['离散选择：经过哪些区域','连续变量：区域内交接点与路径','本集用Drake官方GCS组件实际求解'])
add('convex','凸区域：两点之间的整段也在里面','先认识凸集合。在一个凸区域里任选两个点，它们之间的整条线段仍在区域内。矩形就是最容易想象的例子。这件事特别有用：如果区域已经确认安全，线段两端都在里面，整段就有了区域内的几何保证。前提是区域真的安全，不能先把障碍涂蓝，再宣布世界和平。',[r'(1-\lambda)a+\lambda b\in X',r'0\leq\lambda\leq1'],['凸性：线段封闭性','几何保证依赖安全区域的正确性','安全区域构建本身也需要计算'])
add('regions','先把可用空间表示成安全走廊','黑板上，起点在左边，终点在右边，中间红色柜子不能穿。我们提供左、上、下、右四个安全矩形。它们覆盖了两条绕行走廊，但没有覆盖全部自由空间。这些区域由教学场景直接给出，省下了自动构建区域的步骤；讲义会把这笔建图成本单独列出来。',[r'X_i\subseteq X_{free}'],['蓝/青：给定安全区域','红：静态矩形障碍','区域覆盖不是完整自由空间'])
add('graph','图里的节点，可以是一整块区域','普通图里，一个节点常代表一个固定位置。凸集图把一个凸集合放到节点上，位置可以在集合里优化。我们给每个走廊节点放入口和出口两个点；相邻区域能交接，就添加连接边。于是图不只回答从哪里经过，还允许算法调整在哪里交接。',[r'z_i=(p_i^{in},p_i^{out})',r'z_i\in X_i\times X_i'],['节点中的连续变量不是固定中心点','本集：每个区域一条直线段','图中连边同时约束交接连续性'])
add('choice','选上路还是下路，也是变量','现在有两条图上候选：左、上、右，或者左、下、右。选哪条边，用零或一的变量表达；区域中的点坐标，则是连续变量。这就是混合整数模型的由来。凸集合并没有让所有绕行选择自动变成一个简单凸问题，困难只是被清楚地写出来了。',[r'\phi_e\in\{0,1\}',r'p_i\in\mathbb{R}^2'],['整数：图上路径选择','连续：入口、出口坐标','一般GCS问题仍然有组合难度'])
add('objective','把路径长度，写成一张总账','本集只最小化折线路径长度。每块区域的入口到出口，算一段欧氏距离，再把选中区域的长度加起来。它是几何长度，单位米。没有给机器人排时间，也没有算电机力矩。画面里的移动光点只是沿路线展示，不能把播放快慢当成求解速度。',[r'\min\sum_{i\in\pi}\Vert p_i^{out}-p_i^{in}\Vert_2'],['本集目标：总折线长度/m','正权、静态、二维点机器人','动画按弧长回放，不是求解器迭代'])
add('handover','交接时，两个点必须对上','假设上一区域的出口，与下一区域的入口没对齐，机器人就要瞬移一小截。所以选中一条连接边后，我们要求这两个点相等。这样，交接点同时属于相邻的安全区域，每段又留在自己的凸区域里，最后拼起来才是一条连续可行的路径。',[r'p_i^{out}=p_j^{in}',r'p_i^{out}\in X_i\cap X_j'],['选中边必须满足交接点相等','独立检查区域归属与连续性残差','不能只连区域中心就认为整段安全'])
add('bezier','从直线段，怎样走向曲线？','正式的 G C S 轨迹规划常利用贝塞尔曲线的凸包性质：控制点都在某个凸区域内，整段曲线也在其中。本集先用一阶曲线，也就是直线段，把区域选择和交接点讲透。更高阶曲线、接缝速度与时间安排，需要额外变量和约束，不能看到线条变圆，就认定机器人能平顺执行。',[r'q(s)=\sum_k B_k(s)P_k',r'B_k(s)\geq0,\quad\sum_k B_k(s)=1'],['控制点凸包包住整段贝塞尔曲线','本实验采用一阶特例','平滑、时间、动力学另加约束'])
add('hand','手算：上路和下路各要多长？','先手算这张教学地图。上路交接点是二、一，和三、一。两头各是根号五，中间一米，总长约五点四七二一米。下路交接点是二、负一点五，和三、负一点五，两头各二点五米，中间一米，总共六米。这是当前走廊模型的两条最优分支，接下来用求解器核对。',[r'L_U=2\sqrt{5}+1\approx5.4721',r'L_D=2(2.5)+1=6'],['坐标及单位见实际场景与讲义','图只含上/下两条无环候选分支','解析结果与Drake数值解独立核对'])
add('baseline','交接点不固定在门的正中间','如果把交接点固定在两个重叠区域的中心，上路长度约六点零八六一米。让交接点参与优化后，变成五点四七二一米。两者都在同一条上走廊里，也都通过了几何检查。改善来自交接位置的自由度，不能把它宣传成比所有采样算法都快，或者在所有地图都更短。',[r'L_{center}\approx6.0861\,m',r'L_{optimized}\approx5.4721\,m'],['固定交接中心与优化交接位置','同场景、同上走廊、同长度目标','不作跨规划器耗时排名'])
add('relax','松弛：先让零和一之间也能取值','直接求所有整数选择，可能很贵。常见办法是先做凸松弛，把选边变量暂时放到零和一之间。我们实际运行 Drake，加上 Clarabel 求解器，得到约五米的数值下界。但是上路流量约零点五三九，下路约零点四六一。机器人总不能把自己分成两半，分别绕过柜子再拼起来。',[r'0\leq\phi_e\leq1',r'L_{relax}\approx5.0000\,m'],['真实松弛解：上约0.539，下约0.461','分数流不是可执行路线','本例松弛不紧，不能直接当成最优可行解'])
add('round','舍入以后，重新求一条可行路线','所以还要舍入：从松弛提供的信息里提取候选图路径，固定区域序列后，重新求连续变量。实际程序比较了上下两条分支，选出五点四七二一米的上路。舍入后还要检查入口出口是否对齐、线段是否留在指定区域，以及整段是否碰撞。看到求解成功，只是验收的开始。',[r'\text{relax}\to\text{round}\to\text{restrict}',r'L_{feasible}\approx5.4721\,m'],['Drake实际舍入与固定路径凸求解','三种种子只改变舍入随机数','同一环境重复核对，不是三张测试地图'])
add('bound','下界五米，为什么还不能直接说最优？','下界约五米，可行路线约五点四七二一米，以这个下界为分母，两者相差约百分之九点四四。仅凭这对上下界，还不能证明路线最优。本例图里恰好只有两条候选分支，我们把两条都固定求解，再与解析手算核对，才确认了这个模型里的最优值。大图不能指望永远这样枚举。',[r'L_{LB}\leq L^*_{model}\leq L_{feasible}',r'(5.4721-5)/5\approx9.44\%'],['数值上下界：保留求解容差','两分支完整枚举是独立核验','不能从不紧松弛直接宣称全局最优'])
add('coverage','模型内最短，仍可能漏掉更短路线','再看一条贴近柜子、保留零点零二米间隙的可行折线，长度约五点一七二九米，比刚才还短。它经过了我们没放进安全区域的地方，因此不属于刚才的凸集图模型。没有矛盾：模型内最优，和整个连续自由空间最优，是两个范围。走廊画得保守，就可能付出绕远的代价。',[r'5.1729<5.4721\,m'],['真实可行参考折线，解析检碰通过','参考线超出给定安全区域覆盖','不把参考线宣称为连续空间全局最短'])
add('failure','故意漏画走廊：图上就没有路了','现在故意删掉上、下两个区域，只留左边和右边。柜子旁边明明能绕过去，图里却已经没有连接两侧的走廊，求解器报告模型不可行。这次失败不是让它多迭代几轮就能补好的。先恢复缺失的上走廊，再建立交接边，原来的可行路线才回来。',[r'\text{missing cover}\Rightarrow\text{no graph path}'],['实际GCS返回图上不可行','缺区域/缺连边不等于现实无路','恢复区域，再优化与复检'])
add('body','点能过去，身体却可能擦柜子','老板说，路线验收了，那把小车换大一点。我给它加了零点五米半径，才发现旧上路线离柜子只有零点四米，车身会碰撞。原来安全区域是按点机器人构建的。身体变了，原安全证明的前提也变了，不能只把画面里的模型放大，继续复用原来的蓝色安全标签。',[r'r_{robot}=0.5\,m',r'0.4<0.5\,m'],['点机器人路径不自动适用于有体积机器人','本例用外接方形作保守障碍膨胀','旧路线与膨胀障碍相交，已独立检查'])
add('recovery','恢复：按新身体重建安全区域','我们把障碍做保守膨胀，并重新给出与膨胀障碍分离的安全区域，再用同一个 G C S 模型求解。新的上路线是五点八米，通过了整段几何检查。这仍然是二维教学模型，没有定位误差和制动距离；如果要上真机，这些工程余量也得进入模型与验收。',[r'L_{new}\approx5.8000\,m'],['按新半径重建区域，非旧结果直接缩放','保守膨胀提供充分几何条件','未做真实机器人跟踪、力矩或制动验证'])
add('cost','适合什么场景，也要看准备工作','G C S 的吸引力，是把绕行选择与区域内优化放到同一个框架，还能利用下界评价结果。但构建安全凸区域、建立连接图和求解优化问题，都有成本。固定工位可以考虑复用区域；障碍或机器人模型变化后，原有区域是否有效需要重新确认。这些准备工作，不能藏在演示开始之前。',[r'T=T_{regions}+T_{graph}+T_{solve}+T_{check}'],['区域构建成本与在线求解分开记','本集区域由教学场景人工给定','高维机械臂覆盖、非欧几何需另行处理'])
add('close','选择与优化可以一起做，边界也要一起交代','今天带走三句话：节点可以是一块区域，交接点可以参与优化，松弛结果还要变成可行路线并复检。我是硅宝。算法能把选择困难写进模型，却不能替我把遗漏的需求自动补齐。老板问材料送到了吗？我说快了，刚发现需求里还没写材料有多重。',[r'\text{regions}\to\text{choice+shape}\to\text{verify}'],['GCS静态规划补篇 · 第22集','实际Drake/Clarabel实验、讲义与代码保留','画面与配音含AI辅助制作'])
(B/'lesson.json').write_text(json.dumps(S,ensure_ascii=False,indent=2));(B/'cards.json').write_text(json.dumps(C,ensure_ascii=False,indent=2));print('chapters',len(S),'chars',sum(len(c['text'])for c in S))
